// The TV app's Expo config (ADR 0059): one app for Apple TV and, in 4.5c, Android TV, generated by
// `expo prebuild` with react-native-tvos and its config plugin, which retargets the native project
// to tvOS (https://docs.expo.dev/guides/building-for-tv/). ios/ is never committed.
import type { ExpoConfig } from 'expo/config'
import { withAppleTVIcons, withReactNativeDir } from '../../packages/native/plugins/index.ts'
import pkg from './package.json'

const brand = '../../packages/brand/assets/icons'

const config: ExpoConfig = {
  name: 'highsea',
  slug: 'highsea-tv',
  version: pkg.version,
  // highsea://connect (connectivity.md)
  scheme: 'highsea',
  userInterfaceStyle: 'dark',
  backgroundColor: '#0b0b0c',
  ios: {
    bundleIdentifier: 'tv.highsea.tv',
    infoPlist: {
      // tvOS never asks for the local network, but browsing still declares the type (Apple TN3179)
      NSBonjourServices: ['_highsea._tcp'],
      // servers at home answer over plain HTTP by their LAN address or .local name
      // (https://developer.apple.com/documentation/bundleresources/information-property-list/nsapptransportsecurity/nsallowslocalnetworking)
      NSAppTransportSecurity: { NSAllowsLocalNetworking: true },
      ITSAppUsesNonExemptEncryption: false,
    },
  },
  plugins: [
    ['@react-native-tvos/config-tv', { isTV: true, tvosDeploymentTarget: '16.4' }],
    'expo-router',
    'expo-secure-store',
    [
      'expo-font',
      {
        fonts: [
          '../../packages/brand/fonts/Geist-Regular.ttf',
          '../../packages/brand/fonts/Geist-Medium.ttf',
          '../../packages/brand/fonts/Geist-SemiBold.ttf',
          '../../packages/brand/fonts/GeistMono-Regular.ttf',
          '../../packages/brand/fonts/GeistMono-Medium.ttf',
        ],
      },
    ],
    'expo-video',
    [
      'expo-splash-screen',
      { image: `${brand}/splash/mark.png`, imageWidth: 160, backgroundColor: '#0b0b0c' },
    ],
  ],
}

// plugins written here are applied directly, since ExpoConfig's `plugins` lists names only
// (https://docs.expo.dev/config-plugins/plugins/#apply-a-plugin)
export default withAppleTVIcons(withReactNativeDir(config))
